import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:intl/intl.dart';\nimport '../../../core/providers/core_providers.dart';\nimport '../models/announcement.dart';\nimport '../models/comment.dart';\nimport '../providers/announcement_providers.dart';\n\nclass AnnouncementDetailsScreen extends ConsumerStatefulWidget {\n  final Announcement announcement;\n\n  const AnnouncementDetailsScreen({Key? key, required this.announcement}) : super(key: key);\n\n  @override\n  ConsumerState<AnnouncementDetailsScreen> createState() => _AnnouncementDetailsScreenState();\n}\n\nclass _AnnouncementDetailsScreenState extends ConsumerState<AnnouncementDetailsScreen> {\n  final _commentController = TextEditingController();\n  bool _isSubmitting = false;\n\n  @override\n  void dispose() {\n    _commentController.dispose();\n    super.dispose();\n  }\n\n  Future<void> _submitComment() async {\n    if (_commentController.text.trim().isEmpty) return;\n\n    setState(() => _isSubmitting = true);\n    try {\n      final localStorage = ref.read(localStorageServiceProvider);\n      final studentName = localStorage.getStudentName() ?? 'مجهول';\n      \n      final comment = Comment(\n        id: '', // Supabase auto-generates uuid if configured, or generate manually\n        announcementId: widget.announcement.id,\n        senderName: studentName,\n        content: _commentController.text.trim(),\n        createdAt: DateTime.now(),\n      );\n\n      await ref.read(announcementServiceProvider).addComment(comment);\n      _commentController.clear();\n      // Unfocus keyboard\n      FocusScope.of(context).unfocus();\n    } catch (e) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text(e.toString()), backgroundColor: Colors.red),\n      );\n    } finally {\n      if (mounted) setState(() => _isSubmitting = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final commentsAsync = ref.watch(commentsProvider(widget.announcement.id));\n    final formatter = DateFormat('yyyy-MM-dd HH:mm');\n\n    return Scaffold(\n      appBar: AppBar(title: const Text('التفاصيل')),\n      body: Column(\n        children: [\n          // Announcement Info\n          Container(\n            width: double.infinity,\n            color: widget.announcement.priority ? Colors.red.shade50 : Colors.blue.shade50,\n            padding: const EdgeInsets.all(16.0),\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Text(\n                  widget.announcement.title,\n                  style: TextStyle(\n                    fontSize: 22,\n                    fontWeight: FontWeight.bold,\n                    color: widget.announcement.priority ? Colors.red.shade900 : Colors.black87,\n                  ),\n                ),\n                const SizedBox(height: 8),\n                Text(\n                  formatter.format(widget.announcement.createdAt),\n                  style: const TextStyle(color: Colors.grey),\n                ),\n                const SizedBox(height: 16),\n                Text(\n                  widget.announcement.content,\n                  style: const TextStyle(fontSize: 16, height: 1.6),\n                ),\n              ],\n            ),\n          ),\n          const Divider(height: 1, thickness: 1),\n          \n          // Comments Section\n          const Padding(\n            padding: EdgeInsets.all(16.0),\n            child: Align(\n              alignment: Alignment.centerRight,\n              child: Text('التعليقات', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),\n            ),\n          ),\n          \n          Expanded(\n            child: commentsAsync.when(\n              data: (comments) {\n                if (comments.isEmpty) {\n                  return const Center(child: Text('لا توجد تعليقات بعد. كن أول من يعلق.'));\n                }\n                return ListView.builder(\n                  itemCount: comments.length,\n                  itemBuilder: (context, index) {\n                    final comment = comments[index];\n                    return ListTile(\n                      leading: CircleAvatar(\n                        child: Text(comment.senderName.substring(0, 1)),\n                      ),\n                      title: Text(comment.senderName, style: const TextStyle(fontWeight: FontWeight.bold)),\n                      subtitle: Text(comment.content),\n                      trailing: Text(DateFormat('HH:mm').format(comment.createdAt), style: const TextStyle(fontSize: 12, color: Colors.grey)),\n                    );\n                  },\n                );\n              },\n              loading: () => const Center(child: CircularProgressIndicator()),\n              error: (err, stack) => Center(child: Text('خطأ: $err')),\n            ),\n          ),\n          \n          // Add Comment Input\n          Container(\n            padding: const EdgeInsets.all(12),\n            decoration: BoxDecoration(\n              color: Colors.white,\n              boxShadow: [BoxShadow(color: Colors.grey.shade300, blurRadius: 4, offset: const Offset(0, -2))],\n            ),\n            child: Row(\n              children: [\n                Expanded(\n                  child: TextField(\n                    controller: _commentController,\n                    decoration: InputDecoration(\n                      hintText: 'اكتب تعليقك...', \n                      border: OutlineInputBorder(\n                        borderRadius: BorderRadius.circular(24),\n                      ),\n                      contentPadding: const EdgeInsets.symmetric(horizontal: 16),\n                    ),\n                  ),\n                ),\n                const SizedBox(width: 8),\n                _isSubmitting\n                    ? const CircularProgressIndicator()\n                    : IconButton(\n                        icon: const Icon(Icons.send, color: Colors.blue),\n                        onPressed: _submitComment,\n                      ),\n              ],\n            ),\n          )\n        ],\n      ),\n    );\n  }\n}\n